import { Card, CardContent } from "@/registry/erbium/ui/card";
import {
  Carousel,
  CarouselNext,
  CarouselPrevious,
  CarouselSlide,
  CarouselSlides,
} from "@/registry/erbium/ui/carousel";

export default function CarouselSizeExample() {
  return (
    <Carousel aria-label="Numbers" align="start" className="w-full max-w-sm">
      <CarouselSlides>
        {Array.from({ length: 5 }, (_, index) => (
          <CarouselSlide key={index} className="md:basis-1/2 lg:basis-1/3">
            <Card className="aspect-square">
              <CardContent className="flex min-h-0 flex-1 items-center justify-center">
                <span className="text-display font-semibold">{index + 1}</span>
              </CardContent>
            </Card>
          </CarouselSlide>
        ))}
      </CarouselSlides>
      <CarouselPrevious />
      <CarouselNext />
    </Carousel>
  );
}

import ExampleCarouselSize from "../examples/carousel-size";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleCarouselSize />
  </div>
);

export default Example;
